import React, {useState} from 'react';
import api from '../lib/api';
import { useNavigate } from 'react-router-dom';

export default function Register(){
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const nav = useNavigate();

  async function submit(e){
    e.preventDefault();
    setError('');
    try{
      const r = await api.post('/auth/register',{name, email, password});
      localStorage.setItem('hr_token', r.data.token);
      localStorage.setItem('hr_user', JSON.stringify(r.data.user));
      alert('Registrasi berhasil! Anda sudah login.');
      nav('/');
    }catch(err){
      const data = err.response?.data;
      let msg = 'Registrasi gagal';
      if (data) {
        if (typeof data.message === 'string') {
          msg = data.message;
        } else if (data.message && typeof data.message === 'object') {
          // Ambil pesan pertama dari object errors {field: [messages]}
          const first = Object.values(data.message).flat?.() || Object.values(data.message);
          msg = Array.isArray(first) ? (first[0] || msg) : String(first || msg);
        } else if (typeof data.error === 'string') {
          msg = data.error;
        }
      }
      setError(msg);
    }
  }

  return (
    <div style={{maxWidth:400, margin:'80px auto', padding:20}}>
      <h2>Register - Pembeli</h2>
      <p style={{color:'#666', marginBottom:20}}>Daftar untuk bisa checkout dan melacak pesanan Anda</p>
      {error && (
        <div style={{color:'red', marginBottom:10}}>
          {error}
          {(error.toLowerCase().includes('sudah terdaftar') || error.toLowerCase().includes('has already been taken')) && (
            <div style={{marginTop:8}}>
              Silakan <a href="/login" style={{color:'#f27171', textDecoration:'underline'}}>login</a> dengan email tersebut.
            </div>
          )}
        </div>
      )}
      <form onSubmit={submit}>
        <div style={{marginBottom:12}}>
          <label style={{display:'block', marginBottom:4}}>Nama Lengkap</label>
          <input 
            style={{width:'100%', padding:8, border:'1px solid #ddd'}} 
            value={name} 
            onChange={e=>setName(e.target.value)} 
            placeholder="Nama lengkap" 
            required
          />
        </div>
        <div style={{marginBottom:12}}>
          <label style={{display:'block', marginBottom:4}}>Email</label>
          <input 
            type="email"
            style={{width:'100%', padding:8, border:'1px solid #ddd'}} 
            value={email} 
            onChange={e=>setEmail(e.target.value)} 
            placeholder="email@example.com" 
            required
          />
        </div>
        <div style={{marginBottom:12}}>
          <label style={{display:'block', marginBottom:4}}>Password</label>
          <input 
            type="password" 
            style={{width:'100%', padding:8, border:'1px solid #ddd'}} 
            value={password} 
            onChange={e=>setPassword(e.target.value)} 
            placeholder="password" 
            required
          />
        </div>
        <div style={{marginBottom:12}}>
          <button type="submit" style={{width:'100%', padding:10, background:'#f27171', color:'#fff', border:'none', cursor:'pointer', borderRadius:4}}>
            Daftar
          </button>
        </div>
      </form>
      <div style={{textAlign:'center', marginTop:16}}>
        Sudah punya akun? <a href="/login" style={{color:'#f27171'}}>Login</a>
      </div>
    </div>
  )
}
